fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 and that all Fibonacci numbers up to index n − 1
    // fit in an i32 (i.e., F(n-1) < 2^31).
    let mut ret = Vec::with_capacity(n);
    // Base cases
    ret.push(0);
    ret.push(1);
    // Build the sequence up to length n
    for i in 2..n {
        // Since ret[i-1] and ret[i-2] are guaranteed not to overflow i32
        let next = ret[i - 1] + ret[i - 2];
        ret.push(next);
    }
    ret
}

